// Comparación de hash: compara el hash recibido con la línea base registrada
const entrada = $input.first().json;
const body = entrada.body || entrada;
const hash = String(body.hash_sshd || '').trim().toLowerCase();
const base = String($env.SSHD_BASELINE_HASH || '').trim().toLowerCase();
if (!/^[a-f0-9]{64}$/.test(hash)) throw new Error('El campo hash_sshd no es un SHA-256 válido');
if (!/^[a-f0-9]{64}$/.test(base)) throw new Error('Falta SSHD_BASELINE_HASH en el .env');
return [{ json: {
  hash, base,
  cambio: hash !== base,
  host: body.host || 'nutrianimales-srv01',
  timestamp: body.timestamp || new Date().toISOString()
} }];

// HTTP a GLPI: consulta si hay un Change aprobado y crea o cierra el incidente
const d = $input.first().json;
const API = $env.GLPI_API_URL;
const base = { 'Content-Type': 'application/json' };
if ($env.GLPI_APP_TOKEN && $env.GLPI_APP_TOKEN !== '__cambiar__') base['App-Token'] = $env.GLPI_APP_TOKEN;
const req = (method, path, body, extra = {}) =>
  this.helpers.httpRequest({ method, url: API + path, headers: { ...base, ...extra }, body, json: true });

const corto = h => h ? h.slice(0, 8) + '…' + h.slice(-4) : '—';
const fecha = iso => new Date(iso).toLocaleString('es-CR', { timeZone: 'America/Costa_Rica', hour12: false });
function msg(tipo, titulo, sev, norma, valor, accion, ticket) {
  return [
    `🚨 ALERTA ${tipo} · ${titulo}`,
    'NutriAnimales S.A. | Proyecto II · BCD 9220',
    `Tipo: ${titulo}`,
    `Fecha: ${fecha(d.timestamp)}`,
    `Host: ${d.host}`,
    `Valor detectado: ${valor}`,
    `Severidad: ${sev}`,
    `Norma: ${norma}`,
    `Acción sugerida: ${accion}`,
    `Ticket GLPI: ${ticket ? '#' + ticket : 'sin ticket'}`
  ].join('\n');
}

const ses = await req('GET', '/initSession', undefined, { Authorization: 'user_token ' + $env.GLPI_USER_TOKEN });
base['Session-Token'] = ses.session_token;
const TITULO = 'Cambio no autorizado en sshd_config · ' + d.host;
const valorHash = `hash ${corto(d.hash)} (línea base ${corto(d.base)})`;
const out = [];
try {
  // ID de la categoría "Seguridad > Cambio de configuración" (variable GLPI_CATEGORIA_ID del .env)
  let catId = Number($env.GLPI_CATEGORIA_ID || 0);
  if (!catId) {
    const cats = await req('GET', '/ITILCategory?range=0-500').catch(() => []);
    const cat = (Array.isArray(cats) ? cats : []).find(c => c.name === 'Cambio de configuración');
    catId = cat ? cat.id : 0;
  }
  const comps = await req('GET', '/Computer?range=0-999');
  const srv = comps.find(c => c.name === d.host);
  const tickets = await req('GET', '/Ticket?range=0-200&sort=id&order=DESC');
  const abierto = tickets.find(t => t.name === TITULO && Number(t.status) < 5);

  if (d.cambio) {
    // ¿Existe un Change aprobado y todavía no aplicado para este servidor?
    let aprobado = null;
    if (srv) {
      const links = await req('GET', `/Computer/${srv.id}/Change_Item`).catch(() => []);
      for (const l of (Array.isArray(links) ? links : [])) {
        const ch = await req('GET', `/Change/${l.changes_id}`);
        if (Number(ch.global_validation) === 3 && ![5, 6, 13, 14].includes(Number(ch.status))) { aprobado = ch; break; }
      }
    }
    if (aprobado) {
      out.push({ json: { alerta: 'C1', ticket: null, texto: msg('C1', 'Cambio en configuración crítica', 'MEDIA', 'ISO/IEC 27001 A.8.9',
        valorHash, `Cambio cubierto por el Change #${aprobado.id} aprobado. Al terminar, registrar el nuevo hash como línea base.`, null) } });
    } else if (!abierto) {
      const content = [
        'Alerta C1/C2 generada automáticamente por N8N.',
        `Host: ${d.host}`,
        `Fecha de detección: ${d.timestamp}`,
        `Hash detectado: ${d.hash}`,
        `Hash de línea base: ${d.base}`,
        'Change aprobado en GLPI: No',
        'Severidad: Crítica · SLA de resolución: 1 hora',
        'Acción sugerida: verificar el cambio, registrar y aprobar un Change o revertir la configuración a la línea base.',
        'Controles: ISO/IEC 27001 A.8.9, A.8.32 y A.5.26.'
      ].join('<br>');
      const input = { name: TITULO, content, type: 1, urgency: 5, impact: 5, itilcategories_id: catId };
      if (srv) input.items_id = { Computer: [srv.id] };
      const t = await req('POST', '/Ticket', { input });
      out.push({ json: { alerta: 'C1', ticket: t.id, texto: msg('C1', 'Cambio en configuración crítica', 'CRÍTICA', 'ISO/IEC 27001 A.8.9',
        valorHash, 'Verificar quién modificó sshd_config y comparar el archivo contra la línea base.', t.id) } });
      out.push({ json: { alerta: 'C2', ticket: t.id, texto: msg('C2', 'Cambio sin ticket aprobado', 'CRÍTICA', 'ISO/IEC 27001 A.8.32 · ITIL habilitación de cambios',
        'No existe un Change aprobado en GLPI para ' + d.host, 'Registrar y aprobar un Change en GLPI o revertir sshd_config a la línea base. SLA de resolución: 1 hora.', t.id) } });
    }
    // Si ya hay un incidente abierto por este cambio, no se repiten las alertas.
  } else if (abierto) {
    await req('POST', '/ITILFollowup', { input: { itemtype: 'Ticket', items_id: abierto.id,
      content: `Cierre automático por N8N: el hash de sshd_config volvió a la línea base (${corto(d.hash)}).` } });
    await req('PUT', `/Ticket/${abierto.id}`, { input: { status: 6 } });
    out.push({ json: { alerta: 'CIERRE', ticket: abierto.id, texto: [
      `✅ Incidente #${abierto.id} cerrado automáticamente`,
      'NutriAnimales S.A. | Proyecto II · BCD 9220',
      `Fecha: ${fecha(d.timestamp)}`,
      `Host: ${d.host}`,
      `Valor detectado: hash ${corto(d.hash)} = línea base`,
      'Acción: registrar el Problem con la causa raíz en GLPI.'
    ].join('\n') } });
  }
} finally {
  await req('GET', '/killSession').catch(() => {});
}
return out;

// Buscar SLA vencidos: incidentes críticos abiertos más tiempo que el umbral (alerta C3)
const API = $env.GLPI_API_URL;
const umbral = Number($env.C3_UMBRAL_MINUTOS || 60);
const base = { 'Content-Type': 'application/json' };
if ($env.GLPI_APP_TOKEN && $env.GLPI_APP_TOKEN !== '__cambiar__') base['App-Token'] = $env.GLPI_APP_TOKEN;
const req = (method, path, body, extra = {}) =>
  this.helpers.httpRequest({ method, url: API + path, headers: { ...base, ...extra }, body, json: true });
const fecha = dt => dt.toLocaleString('es-CR', { timeZone: 'America/Costa_Rica', hour12: false });
// GLPI devuelve las fechas en su zona horaria; por defecto se asume UTC
const aFecha = s => new Date(s.replace(' ', 'T') + (($env.GLPI_FECHAS_UTC || 'true') === 'true' ? 'Z' : ''));

const estado = $getWorkflowStaticData('global');
estado.alertados = estado.alertados || [];
const ses = await req('GET', '/initSession', undefined, { Authorization: 'user_token ' + $env.GLPI_USER_TOKEN });
base['Session-Token'] = ses.session_token;
const out = [];
try {
  const tickets = await req('GET', '/Ticket?range=0-200&sort=id&order=DESC');
  const ahora = new Date();
  for (const t of tickets) {
    if (!String(t.name).startsWith('Cambio no autorizado en sshd_config') || Number(t.status) >= 5) continue;
    if (estado.alertados.includes(t.id)) continue;
    const min = Math.floor((ahora - aFecha(t.date)) / 60000);
    if (min < umbral) continue;
    estado.alertados.push(t.id);
    out.push({ json: { alerta: 'C3', ticket: t.id, texto: [
      '🚨 ALERTA C3 · SLA vencido',
      'NutriAnimales S.A. | Proyecto II · BCD 9220',
      'Tipo: SLA vencido',
      `Fecha: ${fecha(ahora)}`,
      `Valor detectado: incidente crítico abierto hace ${min} min (umbral ${umbral} min)`,
      'Severidad: CRÍTICA',
      'Norma: ISO/IEC 27001 A.5.26 · ITIL gestión de niveles de servicio',
      'Acción sugerida: escalar al responsable del SGSI y atender el incidente de inmediato.',
      `Ticket GLPI: #${t.id}`
    ].join('\n') } });
  }
} finally {
  await req('GET', '/killSession').catch(() => {});
}
return out;
